-- ============================================================================
-- 10. KIỂM TRA SAU KHI NẠP
-- ============================================================================
SELECT 'users' AS table_name, COUNT(*) AS row_count FROM users
UNION ALL SELECT 'clients', COUNT(*) FROM clients
UNION ALL SELECT 'freelancers', COUNT(*) FROM freelancers
UNION ALL SELECT 'skills', COUNT(*) FROM skills
UNION ALL SELECT 'freelancer_skills', COUNT(*) FROM freelancer_skills
UNION ALL SELECT 'jobs', COUNT(*) FROM jobs
UNION ALL SELECT 'proposals', COUNT(*) FROM proposals
UNION ALL SELECT 'contracts', COUNT(*) FROM contracts
UNION ALL SELECT 'milestones', COUNT(*) FROM milestones
UNION ALL SELECT 'transactions', COUNT(*) FROM transactions
UNION ALL SELECT 'ledger_entries', COUNT(*) FROM ledger_entries
UNION ALL SELECT 'reviews', COUNT(*) FROM reviews;

-- Phân bố trạng thái
SELECT 'jobs' AS entity, status, COUNT(*) AS n FROM jobs GROUP BY status
UNION ALL SELECT 'proposals', status, COUNT(*) FROM proposals GROUP BY status
UNION ALL SELECT 'contracts', status, COUNT(*) FROM contracts GROUP BY status
UNION ALL SELECT 'milestones', status, COUNT(*) FROM milestones GROUP BY status
UNION ALL SELECT 'transactions', tx_type, COUNT(*) FROM transactions GROUP BY tx_type
UNION ALL SELECT 'users', status, COUNT(*) FROM users GROUP BY status;

-- Các truy vấn đối soát: mọi câu dưới đây phải trả về 0 dòng
SELECT * FROM vw_user_wallet_reconciliation WHERE difference <> 0.00;
SELECT * FROM vw_transaction_trial_balance WHERE status = 'COMPLETED' AND difference <> 0.00;
SELECT * FROM vw_milestone_escrow_reconciliation WHERE difference <> 0.00;
SELECT * FROM vw_user_isa_reconciliation WHERE isa_status <> 'OK';
